import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.BEUshCVJ.js";const g=JSON.parse('{"title":"Providers and keys","description":"","frontmatter":{},"headers":[],"relativePath":"guide/providers.md","filePath":"guide/providers.md","lastUpdated":1792860039000}'),s={name:"guide/providers.md"};function i(a,e,l,c,d,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="providers-and-keys" tabindex="-1">Providers and keys <a class="header-anchor" href="#providers-and-keys" aria-label="Permalink to &quot;Providers and keys&quot;">​</a></h1><p>This page describes each supported provider: where to get a key, where to enter it, how to check it, and the errors you&#39;re most likely to see.</p><p>All keys are stored only in Windows Credential Manager, in entries named <code>MeetCue</code>. They are never written to the settings file or the logs, and the interface only knows whether a key is configured.</p><p>Prices are listed in the <a href="/meetcue/reference/pricing">price reference</a>. Check the provider&#39;s website for current prices.</p><h2 id="soniox" tabindex="-1">Soniox <a class="header-anchor" href="#soniox" aria-label="Permalink to &quot;Soniox&quot;">​</a></h2><p>Speech recognition that handles Chinese and English mixed in one sentence, with built-in sentence-end detection. Billed per hour of audio.</p><ol><li><strong>Get a key</strong>: sign in to the Soniox console and create an API key.</li><li><strong>Enter it</strong>: <strong>Settings › Providers &amp; cost › API keys › Soniox key</strong>, then <strong>Save and verify</strong>.</li><li><strong>Check</strong>: verification lists the real-time models available to your account.</li><li><strong>Endpoint</strong>: Soniox runs several endpoints. Keep <strong>Auto</strong> and run the <a href="/meetcue/guide/latency">latency probe</a> to choose the fastest.</li></ol><p>Common errors: <a href="/meetcue/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a> (key rejected), <a href="/meetcue/troubleshooting/error-codes#mc-asr-002">MC-ASR-002</a> (can&#39;t connect).</p><h2 id="deepgram" tabindex="-1">Deepgram <a class="header-anchor" href="#deepgram" aria-label="Permalink to &quot;Deepgram&quot;">​</a></h2><p>Streaming speech recognition, billed per minute of audio.</p><ol><li><strong>Get a key</strong>: sign in to the Deepgram console, open your project and create an API key with member permissions.</li><li><strong>Enter it</strong>: <strong>Settings › Providers &amp; cost › API keys › Deepgram key</strong>, then <strong>Save and verify</strong>.</li><li><strong>Check</strong>: verification lists your projects and the available speech models.</li><li><strong>Languages</strong>: set <strong>Settings › Audio › Meeting languages</strong>. Deepgram uses its Mandarin model whenever Chinese is selected and its multilingual model otherwise.</li></ol><p>Common errors: <a href="/meetcue/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>, <a href="/meetcue/troubleshooting/error-codes#mc-asr-003">MC-ASR-003</a> (rate limited).</p><h2 id="anthropic" tabindex="-1">Anthropic <a class="header-anchor" href="#anthropic" aria-label="Permalink to &quot;Anthropic&quot;">​</a></h2><p>Claude models for question detection and hints.</p><ol><li><strong>Get a key</strong>: sign in to the Claude Console, open <strong>API keys</strong> and create a key. Add credit or a payment method to the organization.</li><li><strong>Enter it</strong>: <strong>Settings › Providers &amp; cost › API keys › Anthropic key</strong>, then <strong>Save and verify</strong>.</li><li><strong>Check</strong>: verification loads the model list from the API. Models in the <a href="/meetcue/reference/pricing">price reference</a> show their prices; others link to Anthropic&#39;s official pricing page.</li></ol><p>Common errors: <a href="/meetcue/troubleshooting/error-codes#mc-llm-002">MC-LLM-002</a> (key rejected), <a href="/meetcue/troubleshooting/error-codes#mc-llm-003">MC-LLM-003</a> (rate limited), <a href="/meetcue/troubleshooting/error-codes#mc-llm-004">MC-LLM-004</a> (model not available).</p><h2 id="openai-compatible-apis" tabindex="-1">OpenAI-compatible APIs <a class="header-anchor" href="#openai-compatible-apis" aria-label="Permalink to &quot;OpenAI-compatible APIs&quot;">​</a></h2><p>Any service that implements the OpenAI chat completions API with streaming, including self-hosted model servers.</p><ol><li><strong>Base URL</strong>: in <strong>Settings › Providers &amp; cost</strong>, enter the base URL ending in <code>/v1</code>, for example <code>https://llm.example.com/v1</code>.</li><li><strong>Key</strong>: paste the service&#39;s API key under <strong>OpenAI-compatible key</strong>. Leave it empty if the service doesn&#39;t need one.</li><li><strong>Check</strong>: <strong>Save and verify</strong> loads <code>/v1/models</code>. MeetCue has no prices for these models; click <strong>Enter price</strong> next to a model so cost estimates and budgets work.</li></ol><p>Some services don&#39;t report token usage while streaming. Usage and cost then show as zero for them.</p><h2 id="corporate-networks" tabindex="-1">Corporate networks <a class="header-anchor" href="#corporate-networks" aria-label="Permalink to &quot;Corporate networks&quot;">​</a></h2><p>MeetCue uses the Windows certificate store, so certificates installed by your company are trusted. It follows the manual proxy set in Windows Settings (<strong>Network &amp; internet › Proxy</strong>) for all connections, including speech recognition. Automatic configuration scripts are not evaluated; if your network uses one, or to use a different proxy, enter it in <strong>Settings › Providers &amp; cost › Advanced › HTTPS proxy</strong>. If connections fail with <a href="/meetcue/troubleshooting/error-codes#mc-net-001">MC-NET-001</a>, see <a href="/meetcue/troubleshooting/latency#company-network">High latency</a>.</p>',22)])])}const m=o(s,[["render",i]]);export{g as __pageData,m as default};
